data = pd.read_csv("../data/train.csv")

chunks = []
chunk = []
for comment in data["content"]:
    if pd.isna(comment):
        if chunk:
            chunks.append(chunk)
        chunk = []
    else:
        chunk.append(comment)
chunks.append(chunk)

G = glob.split("****")


pd.DataFrame({"comment" : G, "chunks" : chunks}).to_csv("../data/comment_chunk_train.csv") 
